        oneway: isOneWay,
        forward,
        backward,
        bothways,
        turnLanes,
        maxspeed,
        maxspeedLanes,
        psvLanes,
        busLanes,
        taxiLanes,
        hovLanes,
        hgvLanes,
        bicyclewayLanes
