  // modules/pixi/PixiLayerEditBlocks.ts
  var MINZOOM = 4;

  class PixiLayerEditBlocks extends AbstractPixiLayer {
    constructor(scene) {
      super(scene);
      this.id = "edit-blocks";
      this.enabled = true;
    }
    get enabled() {
      return true;
    }
    set enabled(val) {
      this._enabled = true;
    }
    render(frame, viewport) {
      const context = this.context;
      const l10n = context.systems.l10n;
      const locations = context.systems.locations;
      const mapViewport = context.viewport;
      const viewZoom = mapViewport.transform.zoom;
      if (!locations)
        return;
      let blocks = [];
      if (viewZoom >= MINZOOM) {
        blocks = locations.getBlocks(mapViewport.visibleExtent());
        this.renderEditBlocks(frame, viewport, blocks);
      }
      const $explanationRow = context.container().select(".main-content > .map-footer").selectAll(".api-status.blocks").data(blocks, (d) => d.id);
      $explanationRow.exit().remove();
      const $$explanationRow = $explanationRow.enter().insert("div", ".api-status").attr("class", "api-status blocks error");
      $$explanationRow.append("span").attr("class", "explanation-item").text((d) => d.properties.text);
      $$explanationRow.append("a").attr("target", "_blank").attr("href", (d) => d.properties.url).text(l10n?.t("rapid_catalog.more_info") || "More Info");
    }
    renderEditBlocks(frame, viewport, blocks) {
      const parentContainer = this.scene.groups.get("blocks");
      if (!parentContainer)
        return;
      const blockStyle = {
        fill: { pattern: "construction", color: 0, opacity: 0.7, type: "full" }
      };
      for (const d of blocks) {
        const dataID = d.id;
        const parts = d.geoms.parts;
        for (let i = 0;i < parts.length; ++i) {
          const part = parts[i];
          if (!part.world || part.type !== "Polygon")
            continue;
          const featureID = `${this.layerID}-${dataID}-${i}`;
          let feature = this.features.get(featureID);
          if (!feature) {
            feature = new PixiFeaturePolygon(this, featureID);
            feature.allowInteraction = false;
            feature.style = blockStyle;
            feature.parentContainer = parentContainer;
            feature.container.cursor = "not-allowed";
          }
          if (feature.data !== d || feature.geometry !== part) {
            feature.geometry = part;
            feature.data = d;
          }
          feature.update(viewport);
          this.retainFeature(feature, frame);
        }
      }
    }
  }

  // modules/pixi/PixiLayerKartaPhotos.ts
  var MINZOOM2 = 12;
  var KARTAVIEW_BLUE = 2147583;
  var SELECTED = 16772608;
