          const node1 = nodes[i];
          const node2 = nodes[i + 1];
          const coord1 = graph.geometry(node1).parts[0].world?.coords;
          const coord2 = graph.geometry(node2).parts[0].world?.coords;
          if (!coord1 || !coord2)
            continue;
          const dist = vecLength(coord1, coord2);
          const rotation = vecAngle(coord1, coord2);
          const coord = vecInterp(coord1, coord2, 0.5);
          const loc = projWorldToWgs84(coord);
