  // modules/pixi/RenderFrame.ts
  class RenderFrame {
    id;
    time;
    zoom;
    dirtyScene;
    contentChanged;
    requested;
    changedLayerIDs;
    cullBox;
    held;
    viewBox;
    deadline;
    urgent;
    drawDebt;
    waitingInView;
    unfinished;
    appMs;
    layers;
    draw;
    constructor(id, zoom) {
      this.id = id;
      this.time = performance.now();
      this.zoom = zoom;
      this.dirtyScene = false;
      this.contentChanged = true;
      this.requested = true;
      this.changedLayerIDs = new Set;
      this.cullBox = new Extent;
      this.held = false;
      this.viewBox = new Extent;
      this.deadline = Infinity;
      this.urgent = false;
      this.drawDebt = 0;
      this.waitingInView = 0;
      this.unfinished = false;
      this.appMs = 0;
      this.layers = new Map;
      this.draw = null;
    }
    changedFor(layerID) {
      return this.contentChanged || this.changedLayerIDs.has(layerID);
    }
    requestedFor(layerID) {
      return this.requested || this.changedLayerIDs.has(layerID);
    }
    hasTime() {
      return performance.now() + this.drawDebt < this.deadline;
    }
    get cpuMs() {
      return this.appMs + (this.draw?.ms ?? 0);
    }
    toJSON() {
      return {
        id: this.id,
        zoom: this.zoom,
        dirtyScene: this.dirtyScene,
        contentChanged: this.contentChanged,
        changedLayerIDs: [...this.changedLayerIDs],
        cullBox: this.cullBox.rectangle(),
        held: this.held,
        urgent: this.urgent,
        unfinished: this.unfinished,
        appMs: this.appMs,
        layers: Object.fromEntries(this.layers),
        draw: this.draw
      };
    }
  }

