      $container.append("svg").attr("class", "preset-icon-category-border").attr("width", `${px}px`).attr("height", `${px}px`).attr("viewBox", `0 0 ${px} ${px}`).append("path").attr("fill", color).attr("fill-opacity", opacity ?? null).attr("stroke", color).attr("d", FOLDER_PATH);
