      $$label.append("button").attr("class", "member-zoom").attr("title", l10n.t("icons.zoom_to")).call(uiIcon("#rapid-icon-framed-dot", "monochrome")).on("click", this._zoomToRelation);
      const $$wrap = $$items.append("div").attr("class", "form-field-input-wrap form-field-input-member");
