      const $$newLabel = $$newMembership.append("label").attr("class", "field-label");
      $$newLabel.append("input").attr("type", "text").attr("class", "member-entity-input").call(utilNoAuto);
      $$newLabel.append("button").attr("class", "remove member-delete").call(uiIcon("#rapid-operation-delete")).on("click", () => {
        $list.selectAll(".member-row-new").remove();
      });
      const $$newWrap = $$newMembership.append("div").attr("class", "form-field-input-wrap form-field-input-member");
      $$newWrap.append("input").attr("class", "member-role").property("type", "text").call(utilNoAuto);
      $newMembership = $newMembership.merge($$newMembership);
      $newMembership.selectAll(".member-entity-input").attr("placeholder", l10n.t("inspector.choose_relation"));
      $newMembership.selectAll(".member-role").attr("placeholder", l10n.t("text.role"));
      $newMembership.selectAll(".member-entity-input").on("blur", cancelEntity).call(this._nearbyCombo.on("accept", acceptEntity).on("cancel", cancelEntity).attach);
      let $addRow = $selection.selectAll(".add-row").data([0]);
