  // modules/modes/AddNoteMode.ts
  var DEBUG = false;

  class AddNoteMode extends AbstractMode {
    constructor(context) {
      super(context);
      this.id = "add-note";
      this._click = this._click.bind(this);
      this._cancel = this._cancel.bind(this);
    }
    enter() {
      if (DEBUG) {
        console.log("AddNoteMode: entering");
      }
      this._active = true;
      const context = this.context;
      context.enableBehaviors(["hover", "draw", "mapInteraction"]);
      context.behaviors.draw.on("click", this._click).on("cancel", this._cancel).on("finish", this._cancel);
      return true;
    }
    exit() {
      if (!this._active)
        return;
      this._active = false;
      if (DEBUG) {
        console.log("AddNoteMode: exiting");
      }
      const context = this.context;
      context.behaviors.draw.off("click", this._click).off("cancel", this._cancel).off("finish", this._cancel);
    }
    _click(eventData) {
      const context = this.context;
      const osm = context.services.osm;
      const viewport = context.viewport;
      const point = eventData.coord.map;
      const loc = viewport.unproject(point);
      if (!osm)
        return;
      const props = { type: "note", serviceID: "osm", spatialID: "osm-notes", loc, isNew: true, status: "open", comments: [] };
      const note = new MarkerData(context, props);
      osm.replaceNote(note);
      context.enter("select", { selection: [note.dataID] });
    }
    _cancel() {
      this.context.enter("browse");
    }
  }

