        const $imageWrap = $wrapper.selectAll(".osc-image-wrap");
        $wrapper.transition().duration(100).call(this._imgZoom.transform, identity3);
        $imageWrap.selectAll(".osc-image").remove();
        const sequence = spatial.getItem("kartaview-sequences", image?.props?.sequenceID);
        const r = sequence?.props?.rotation ?? 0;
        $imageWrap.append("img").attr("class", "osc-image").attr("src", this._hires ? image.props.imageHighUrl ?? "" : image.props.imageMedUrl ?? "").style("transform", `rotate(${r}deg)`);
