      const photos = context.systems.photos;
      const spatial = context.systems.spatial;
      const $wrapper = context.container().select(".photoviewer .osc-wrapper");
      const $options = $wrapper.selectAll(".photo-options");
      let $label = $options.selectAll(".hires").data([0]);
      const $$label = $label.enter().append("label").attr("for", "osc-hires-input").attr("class", "hires");
      $$label.append("input").attr("type", "checkbox").attr("id", "osc-hires-input").on("click", (e) => {
        e.stopPropagation();
        this._hires = !this._hires;
        this.selectImageAsync(photos.currPhotoID);
      });
      $$label.append("span");
      $label = $label.merge($$label);
      $label.selectAll("#osc-hires-input").property("checked", this._hires);
      $label.selectAll("span").text(l10n.t("photos.hires"));
