      if (props.captured_by) {
        $attribution.append("span").attr("class", "captured_by").text(props.captured_by);
        $attribution.append("span").text("|");
      }
      if (props.captured_at) {
        $attribution.append("span").attr("class", "captured_at").text(l10n.displayShortDate(props.captured_at));
        $attribution.append("span").text("|");
      }
      $attribution.append("a").attr("class", "image-link").attr("target", "_blank").attr("href", `https://kartaview.org/details/${props.sequenceID}/${props.sequenceIndex}/track-info`).text("kartaview.org");
